// Gridline — built-in demo songs (original content made with the built-in instruments).
#pragma once
#include <string>
#include <string_view>
#include "Song.h"

namespace gl {

// J-135: "Gridline", the demo song the app and `gridline demo` open (liquid drum & bass, 174 BPM,
// eight sections). Generated by tools/make_demo_song.py into assets/demo/Gridline.gridline.json and
// compiled into the programs (cmake/EmbedDemo.cmake), so it needs no files at run time.
// Falls back to a new empty song (and logs why) if the embedded document cannot be read (never expected).
Song makeDemoTrack();
// Parses the embedded document; false (with the reason) if it does not load.
bool loadDemoTrack(Song& out, std::string* err = nullptr);
// The embedded project document (JSON text).
std::string_view demoSongJson();

}  // namespace gl
